                        { offset: 1, color: 'rgba(255, 122, 0, 0.01)' }  // Some suavemente perto do zero
                    ]
                }
            },
            lineStyle: {
                width: 3                // Espessura robusta da linha principal
            }
        }],

        // LEGENDA NO FOOTER E TRAVADA
        legend: {
            show: true,
            bottom: 5,                  // Coloca a legenda lá no rodapé (Footer)
            selectedMode: false,        // DESATIVA O CLIQUE (Clicar não faz a linha sumir!)
            textStyle: {
                color: '#A9B4C2',
                fontFamily: 'sans-serif'
            }
        },

        // AJUSTE DOS EIXOS (Igual às imagens de referência)
        xAxis: {

            axisLine: { show: false },  // Limpa a linha do eixo X
            splitLine: { show: false },  // Remove grades verticais
            axisLabel: {
                color: '#A9B4C2',
                margin: 12              // Afasta o texto das horas um pouco da linha do eixo
            }
        },
        yAxis: {
            min: 0,
            max: 100,
            splitLine: {
