};

return msg;

// 1. Array de estados possíveis para cada componente para criar variedade na simulação
const estadosMQTT = ["ONLINE", "ONLINE", "ONLINE", "OFFLINE"];
const estadosSensores = ["OK", "OK", "OSCILANDO", "ERRO"];
const estadosDB = ["CONECTADO", "CONECTADO", "LENTO", "DESCONECTADO"];

// 2. Sorteia um estado aleatório para cada um deles
let mqttSorteado = estadosMQTT[Math.floor(Math.random() * estadosMQTT.length)];
let sensoresSorteados = estadosSensores[Math.floor(Math.random() * estadosSensores.length)];
let dbSorteado = estadosDB[Math.floor(Math.random() * estadosDB.length)];

// 3. Captura o horário exato em tempo real (Formato HH:MM:SS)
let agora = new Date();
let horaFormatada = agora.toTimeString().split(' ')[0];

// 4. Monta o objeto JSON enviando também o tempo do próximo intervalo (10 segundos)
msg.payload = {
    mqtt: mqttSorteado,
    sensores: sensoresSorteados,
    db: dbSorteado,
    lastSeen: horaFormatada,
    intervalo: 10 // Define dinamicamente o tempo de 10s para o card Vue
};

return msg;

// Captura a data e hora atual
let dataAtual = new Date().toLocaleString("pt-BR", { timeZone: "America/Recife" });

// Define um assunto mais descritivo e profissional
msg.topic = "🚨 Alerta de Qualidade da Água - Ação Necessária";

// Formata o corpo do e-mail em HTML
msg.payload = `
    <h2>⚠️ Alerta Automático de Telemetria</h2>
    <p>O sistema de monitoramento contínuo detectou uma anomalia sustentada nos níveis de turbidez da água do reservatório.</p>
    <ul>
        <li><strong>Status:</strong> ${msg.payload.mensagem}</li>
        <li><strong>Data da ocorrência:</strong> ${dataAtual}</li>
        <li><strong>Ação Recomendada:</strong> Inspeção visual imediata do recipiente e avaliação para limpeza.</li>
    </ul>
    <hr>
    <p><small><em>Este é um e-mail automático gerado pelo ESP32 via Node-RED. Por favor, não responda.</em></small></p>
`;

return msg;

let dados = msg.payload;

// Garante que os dados existem
if (!dados || !dados.modo) return null;

// 1. Mensagem para o Gráfico de Latência
let msgLatencia = {
    topic: dados.modo === "ON" ? "Vertente 1: O(n) Deslocamento" : "Vertente 2: O(1) Circular",
    payload: Number(dados.latencia_us)
};

// 2. Mensagem para o Gráfico de Memória Heap
let msgHeap = {
    topic: "Heap Livre (" + dados.modo + ")",
    payload: Number(dados.heap_livre)
};

// Envia a latência pela saída 1 e o heap pela saída 2
return [msgLatencia, msgHeap];

// ╔══════════════════════════════════════════════════════════════════════╗
// ║  PROCESSAR TELEMETRIA · O(n) Deslocamento vs O(1) Buffer Circular      ║
// ║  Entrada: msg.payload = conteúdo do Dados_brutos.json (JSONL ou array) ║
// ║  Saída:   msg.payload = objeto D com todas as métricas derivadas       ║
// ╚══════════════════════════════════════════════════════════════════════╝
let raw = msg.payload;
let lotes = [];

if (typeof raw === 'string') {
    // JSONL: um objeto JSON por linha
    const lines = raw.split('\n');
    for (const line of lines) {
        const s = line.trim();
        if (!s) continue;
        try { lotes.push(JSON.parse(s)); } catch (e) { /* ignora linha inválida */ }
    }
    // fallback: arquivo pode ser um array JSON único
    if (!lotes.length) {
        try { const arr = JSON.parse(raw); if (Array.isArray(arr)) lotes = arr; } catch (e) {}
    }
} else if (Array.isArray(raw)) {
    lotes = raw;
} else if (raw && Array.isArray(raw.lotes)) {
    lotes = raw.lotes;
}

if (!lotes.length) {
    node.status({ fill: 'red', shape: 'ring', text: 'nenhum lote lido' });
    node.error('Nenhum lote encontrado no arquivo', msg);
    return null;
}

// ── helpers estatísticos ──
const mean   = a => a.reduce((s, x) => s + x, 0) / a.length;
const pstdev = a => { const m = mean(a); return Math.sqrt(mean(a.map(x => (x - m) ** 2))); };
const round  = (x, d = 0) => { const f = 10 ** d; return Math.round(x * f) / f; };

function linreg(xs, ys) {
    const n = xs.length;
    const sx = xs.reduce((s, x) => s + x, 0), sy = ys.reduce((s, y) => s + y, 0);
    const sxx = xs.reduce((s, x) => s + x * x, 0), sxy = xs.reduce((s, x, i) => s + x * ys[i], 0);
    const slope = (n * sxy - sx * sy) / (n * sxx - sx * sx);
    const intercept = (sy - slope * sx) / n;
    const ybar = sy / n;
    const sstot = ys.reduce((s, y) => s + (y - ybar) ** 2, 0);
    const ssres = ys.reduce((s, y, i) => s + (y - (slope * xs[i] + intercept)) ** 2, 0);
    const r2 = sstot ? 1 - ssres / sstot : 1;
    return { slope, intercept, r2 };
}

// ── agrupar por (modo, tam) ──
const lat = {}, heap = {};
const key = (m, t) => m + '|' + t;
for (const L of lotes) {
    const k = key(L.modo, L.tam);
    (lat[k]  = lat[k]  || []).push(L.latencia_us);
    (heap[k] = heap[k] || []).push(L.heap_livre);
}

const NS = [5, 100, 500, 1000, 2000];
const BASELINE = 254672; // heap livre inicial (referência ESP32)

// ── 1. Latência por N (avg/max/min/std) ──
const lat_by_n = NS.map(tam => {
    const row = { tam };
    [['ON', 'on'], ['O1', 'o1']].forEach(([m, p]) => {
        const v = lat[key(m, tam)];
        if (v && v.length) {
            row[p + '_avg'] = round(mean(v), 1);
            row[p + '_max'] = Math.max.apply(null, v);
            row[p + '_min'] = Math.min.apply(null, v);
            row[p + '_std'] = v.length > 1 ? round(pstdev(v), 1) : 0;
        } else { row[p + '_avg'] = null; row[p + '_max'] = null; row[p + '_min'] = null; row[p + '_std'] = null; }
    });
    return row;
});

// ── 2. Heap por N + custo por elemento ──
const heap_by_n = NS.map(tam => {
    const row = { tam };
    [['ON', 'on'], ['O1', 'o1']].forEach(([m, p]) => {
        const v = heap[key(m, tam)];
        if (v && v.length) {
            const mm = mean(v);
            row[p + '_avg'] = Math.round(mm);
            row[p + '_per_el'] = tam ? round((BASELINE - mm) / tam, 1) : 0;
        } else { row[p + '_avg'] = null; row[p + '_per_el'] = null; }
    });
    return row;
});

// ── 3. Regressão linear → prova de complexidade ──
const onTams = NS.filter(t => lat[key('ON', t)]);
const onAvg  = onTams.map(t => mean(lat[key('ON', t)]));
const o1Tams = [100, 500, 1000, 2000].filter(t => lat[key('O1', t)]);
const o1Avg  = o1Tams.map(t => mean(lat[key('O1', t)]));
const rOn = linreg(onTams, onAvg), rO1 = linreg(o1Tams, o1Avg);
const reg = {
    on: { slope: round(rOn.slope, 5), intercept: round(rOn.intercept, 3), r2: round(rOn.r2, 4) },
    o1: { slope: round(rO1.slope, 6), intercept: round(rO1.intercept, 3), r2: round(rO1.r2, 4) }
};

// ── 4 & 5. Heap e latência por lote ──
const heap_lote = {}, lat_lote = {};
[100, 500, 1000, 2000].forEach(tam => {
    const hs = { on: [], o1: [] }, ls = { on: [], o1: [] };
    [['ON', 'on'], ['O1', 'o1']].forEach(([m, p]) => {
        const grp = lotes.filter(L => L.modo === m && L.tam === tam).sort((a, b) => a.lote - b.lote);
        hs[p] = grp.map(L => ({ lote: L.lote, heap: L.heap_livre }));
        ls[p] = grp.map(L => ({ lote: L.lote, lat: L.latencia_us }));
    });
    heap_lote[tam] = hs; lat_lote[tam] = ls;
});

// ── 6. Cold-start vs Steady-state (origem do jitter) ──
const cold_steady = [];
onTams.forEach(tam => {
    const grp = lotes.filter(L => L.modo === 'ON' && L.tam === tam);
    const l1 = grp.filter(L => L.lote === 1).map(L => L.latencia_us);
    const rest = grp.filter(L => L.lote > 1).map(L => L.latencia_us);
    if (l1.length && rest.length) {
        const cold = l1[0], steady = round(mean(rest), 1);
        cold_steady.push({ tam, cold, steady, delta: round(steady - cold, 1) });
    }
});

// ── 7. Séries temporais (ON & O1, tam=100, lote=1, 80 amostras) ──
function serie(m, tam, lote, n) {
    n = n || 80;
    const L = lotes.find(x => x.modo === m && x.tam === tam && x.lote === lote);
    if (!L) return { tz: [], ts: [] };
    const ams = L.amostras.slice(0, n);
    return { tz: ams.map(a => a.tz), ts: ams.map(a => a.ts) };
}
const sOn = serie('ON', 100, 1), sO1 = serie('O1', 100, 1);
const ts_series = { tz_on: sOn.tz, ts_on: sOn.ts, tz_o1: sO1.tz, ts_o1: sO1.ts };

// ── 8. Histograma de Δts (distribuição dos intervalos) ──
const hist = { burst: 0, mid: 0, periodo: 0, gargalo: 0 };
let totDeltas = 0;
for (const L of lotes) {
    const ts = L.amostras.map(a => a.ts);
    for (let i = 1; i < ts.length; i++) {
        const d = ts[i] - ts[i - 1]; totDeltas++;
        if (d <= 5) hist.burst++;
        else if (d <= 100) hist.mid++;
        else if (d <= 130) hist.periodo++;
        else hist.gargalo++;
    }
}
hist.total = totDeltas;

// ── 9. Throughput (amostras/ms) ──
const thru = [100, 500, 1000, 2000].map(tam => {
    const row = { tam };
    [['ON', 'on'], ['O1', 'o1']].forEach(([m, p]) => {
        const grp = lotes.filter(L => L.modo === m && L.tam === tam);
        const rates = [];
        grp.forEach(L => {
            const ts = L.amostras.map(a => a.ts);
            const span = ts[ts.length - 1] - ts[0];
            if (span > 0) rates.push((ts.length - 1) / span * 1000);
        });
        row[p] = rates.length ? round(mean(rates), 2) : null;
    });
    return row;
});

// ── 10. Estatística de turbidez por modo ──
const tz_stats = [['ON', 'on'], ['O1', 'o1']].map(pair => {
    const m = pair[0];
    const allz = [];
    lotes.forEach(L => { if (L.modo === m) L.amostras.forEach(a => allz.push(a.tz)); });
    return { modo: m, mean: round(mean(allz), 2), std: round(pstdev(allz), 2), min: Math.min.apply(null, allz), max: Math.max.apply(null, allz) };
});

// ── montar objeto final ──
const totalAmostras = lotes.reduce((s, L) => s + L.amostras.length, 0);
const lat2000on = (lat_by_n.find(r => r.tam === 2000) || {}).on_avg;
const lat2000o1 = (lat_by_n.find(r => r.tam === 2000) || {}).o1_avg;
const speedup = lat2000o1 ? round(lat2000on / lat2000o1, 1) : null;

const D = {
    meta: { total_lotes: lotes.length, total_amostras: totalAmostras, speedup_2000: speedup,
            gerado_em: new Date().toISOString() },
    lat_by_n, heap_by_n, reg, heap_lote, lat_lote, cold_steady, ts_series, hist, thru, tz_stats
};

msg.payload = D;
msg.topic = 'telemetria_processada';
node.status({ fill: 'green', shape: 'dot', text: lotes.length + ' lotes · ' + totalAmostras + ' amostras' });
return msg;
